import { z } from 'zod';

// `code` is auto-generated by the CRUD factory (SUPP-0001, SUPP-0002, ...)
// unless the client supplies one explicitly — same convention as every
// other master (see crudFactory.js's nextCode()).
export const createSupplierSchema = z.object({
  code: z.string().trim().min(1).optional(),
  name: z.string().trim().min(1, 'Supplier name is required'),
  group: z.string().trim().optional().nullable(),
  phone: z.string().trim().optional().nullable(),
  email: z.string().trim().email('Enter a valid email').optional().or(z.literal('')).nullable(),
  gstNo: z.string().trim().optional().nullable(),
  city: z.string().trim().optional().nullable(),
  state: z.string().trim().optional().nullable(),
  paymentTerms: z.string().trim().optional().nullable(),
  status: z.enum(['ACTIVE', 'INACTIVE']).default('ACTIVE'),
});

export const updateSupplierSchema = createSupplierSchema.partial();
